-- Recall@10 = overlap with the fullscan IDs / 10.
DROP TABLE IF EXISTS knn_rescore_check;
CREATE TABLE knn_rescore_check (vec float_vector knn_type='hnsw' knn_dims='16' hnsw_similarity='cosine' quantization='1bit');
FLUSH RAMCHUNK knn_rescore_check;

-- Exact fullscan ground truth
SELECT id, knn_dist() FROM knn_rescore_check WHERE knn(vec,10,(-0.2646790,0.9178162,0.2521362,-0.2643433,-0.6706238,0.3580627,-0.6097412,0.4703979,0.4526978,-0.0179749,-0.1361694,0.8511658,0.1656494,-0.7125549,-0.1528320,0.1668396),{fullscan=1}) ORDER BY knn_dist() ASC, id ASC LIMIT 10;

-- HNSW plus rescore, implicit max_matches
SELECT id, knn_dist() FROM knn_rescore_check WHERE knn(vec,10,(-0.2646790,0.9178162,0.2521362,-0.2643433,-0.6706238,0.3580627,-0.6097412,0.4703979,0.4526978,-0.0179749,-0.1361694,0.8511658,0.1656494,-0.7125549,-0.1528320,0.1668396),{ef=2000,oversampling=3.0,rescore=1,early_termination=0}) ORDER BY knn_dist() ASC, id ASC LIMIT 10;

-- HNSW plus rescore, explicit max_matches=10
SELECT id, knn_dist() FROM knn_rescore_check WHERE knn(vec,10,(-0.2646790,0.9178162,0.2521362,-0.2643433,-0.6706238,0.3580627,-0.6097412,0.4703979,0.4526978,-0.0179749,-0.1361694,0.8511658,0.1656494,-0.7125549,-0.1528320,0.1668396),{ef=2000,oversampling=3.0,rescore=1,early_termination=0}) ORDER BY knn_dist() ASC, id ASC LIMIT 10 OPTION max_matches=10;

DROP TABLE knn_rescore_check;
